<?php
declare(strict_types=1);
if(getenv('RUN_FISCAL_MARIADB_TESTS')!=='1'){echo "Fiscal02Concurrency SKIPPED\n";exit;}$cfg=require __DIR__.'/../config.php';$d=$cfg['db'];$pdo=new PDO(sprintf('mysql:host=%s;port=%s;dbname=mini_erp_tenant_14;charset=utf8mb4',$d['host'],$d['port']),$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$tenant=990000+random_int(1,999);$est=880000+random_int(1,999);$spec=[];foreach([['55',1],['55',12],['65',1]] as [$model,$series])for($i=0;$i<7;$i++)$spec[]=[$model,$series,($series*100000)+($model==='65'?65000:55000)+$i];try{$s=$pdo->prepare("INSERT INTO fiscal_series(tenant_id,establishment_id,model,series,next_number,environment,emission_type,process_version,active) VALUES(?,?,?,?,1,2,1,'TEST_ONLY_CONCURRENCY',1)");foreach([['55',1],['55',12],['65',1]] as $key)$s->execute([$tenant,$est,...$key]);$workers=[];foreach($spec as [$model,$series,$doc]){$cmd=['C:/xampp/php/php.exe',__DIR__.'/helpers/FiscalNumberWorker.php',(string)$tenant,(string)$est,$model,(string)$series,(string)$doc];$pipes=[];$proc=proc_open($cmd,[1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($proc))throw new RuntimeException('worker');$workers[]=[$proc,$pipes,$model,$series];}$numbers=[];foreach($workers as [$proc,$pipes,$model,$series]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($proc);if($code!==0)throw new RuntimeException("worker {$code}: {$err}");$row=json_decode($out,true,512,JSON_THROW_ON_ERROR);$numbers[$model.'/'.$series][]=(int)$row['fiscal_number'];}foreach($numbers as $key=>$list){sort($list);if($list!==range(1,7)||count($list)!==count(array_unique($list)))throw new RuntimeException("duplicidade {$key}");}echo "Fiscal02Concurrency OK (21 processos; cross-series)\n";}finally{$pdo->prepare('DELETE FROM fiscal_number_reservations WHERE tenant_id=? AND establishment_id=?')->execute([$tenant,$est]);$pdo->prepare('DELETE FROM fiscal_series_audit WHERE tenant_id=? AND establishment_id=?')->execute([$tenant,$est]);$pdo->prepare('DELETE FROM fiscal_series WHERE tenant_id=? AND establishment_id=?')->execute([$tenant,$est]);}
